-- ============================================================================
-- SEDIMA Parc — complément du relevé de transport (RECAP TONNAGE HEBDOMMADAIRE.11X.xlsx).
--
-- **Ce n'est pas une migration.** Écrit par `scripts/charger-releve-complement.mts` :
-- les seuls voyages postérieurs au 2026-09-03, dernière date du relevé en base.
-- 178 voyages du 2026-09-04 au 2026-09-17 — 428 t par le parc, 3515 t par les transporteurs.
-- Écartés : camion SEDIMA absent du parc (AA131FX) 1 t.
--
-- Rejouable : `on conflict (numero) do nothing`.
-- ============================================================================

on conflict (numero) do nothing;

select mode, count(*) as voyages, sum(tonnage) as tonnes, min(date) as du, max(date) as au
  from releve_transport where date > '2026-09-03' group by mode;
